/**
 * Benchmark configuration - defines which functions to benchmark per workspace.
 *
 * This file is generated by _internal-tools/generate-benchmark-config.ts.
 * Existing case metadata (fixtureSize, canonicalName, args) is preserved when possible.
 */

/**
 * Top-level benchmark config for a workspace.
 */
export interface BenchmarkConfig {
  /** Workspace name that owns the benchmark cases. */
  workspace: string
  /** Benchmark cases to execute for the workspace. */
  cases: BenchmarkCase[]
}

/**
 * One benchmark case entry.
 */
export interface BenchmarkCase {
  /** Exported function name to benchmark. */
  name: string
  /** Fixture size used to build input data. */
  fixtureSize: 'small' | 'medium' | 'large'
  /** Relative module path used for dynamic import. */
  importPath: string
  /** Canonical alias target when this case maps to another function. */
  canonicalName?: string | undefined
  /** Optional argument factory; when present, fixture values are ignored. */
  args?: (() => unknown[]) | undefined
}

